def get(url):
    for _ in range(6):
        r = subprocess.run(["curl", "-sS", "--max-time", "20", "-A", "EdFringeNow-research/1.0", url], capture_output=True, text=True)
        try:
            return json.loads(r.stdout)
        except Exception:
            time.sleep(2)
    raise SystemExit("failed " + url)


